        },
        {
          "source": "netlist",
          "quote": "U6.6(SENSE,input)"
        },
        {
          "source": "spec",
          "quote": "USB power-path controller intended to OR/protect a USB power input"
        },
        {
          "source": "spec",
          "quote": "need reverse current protection mostly"
        }
